 {modal==='Serah-terima kas'&&<><p className="hint">Untuk mengganti petugas saat toko tetap buka. Pesanan dan saldo toko diteruskan.</p><section className="workflow-step"><h3>1 · Hitung uang laci</h3><Field label="Uang fisik yang dihitung (Rp)" value={f('physical')} type="number" onChange={v=>write('physical',v)}/><button disabled={busy} onClick={()=>run(action('count','Rutin',{amount:f('physical'),handover:true},'',0,null))}>{s.cash.countPurpose==='handover'?'Simpan revisi hitungan':'Simpan hitungan'}</button></section>{s.cash.countPurpose==='handover'&&s.cash.count!==undefined&&<><p className="callout good">Hitungan tersimpan {money(s.cash.count)} · Selisih {money(s.cash.count-(s.cash.segments.at(-1)!.baseline+expected(s)-s.cash.segments.at(-1)!.startExpected))}</p><section className="workflow-step"><h3>2 · Petugas baru memeriksa uang diterima</h3><Choice label="Petugas penerima laci" value={f('next')} options={['owner','a','b'].filter(x=>x!==s.cash.segments.at(-1)?.actor)} onChange={v=>write('next',v)}/><Field label="PIN demo petugas penerima" value={f('pin')} type="password" onChange={v=>write('pin',v)} maxLength={6}/><Field label="Uang yang benar-benar diterima (Rp)" value={f('accepted')} type="number" onChange={v=>write('accepted',v)}/><Field label="Alasan selisih / pengambilalihan" value={f('reason')} onChange={v=>write('reason',v)}/>{s.actor==='owner'&&<Tick label="Petugas lama tidak hadir · pengambilalihan owner" value={b('takeover')} onChange={v=>tick('takeover',v)}/>}</section><section className="workflow-step"><h3>3 · Selesaikan serah-terima</h3><button className="primary" disabled={f('physical')!==String(s.cash.count)||!f('next')||!f('accepted')||f('pin').length!==6} onClick={()=>run(action('handover','Rutin',{actor:f('next'),pin:f('pin'),accepted:f('accepted'),takeover:b('takeover')},f('reason'),0,null))}>Selesaikan serah-terima kas</button><p className="footnote">PIN identitas contoh: 123456. Bukan autentikasi nyata.</p></section></>}</>}
